class Solution(object):
    def singleNonDuplicate(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        n = len(nums)
        left, right = 0, n - 1
        while left < right:
            mid = (left + right) // 2
            if mid % 2 == 0:
                if mid + 1 < n and nums[mid] == nums[mid + 1]:
                    left = mid + 1
                else:
                    right = mid
            else:
                if mid - 1 >= 0 and nums[mid] == nums[mid - 1]:
                    left = mid + 1
                else:
                    right = mid
        return nums[right]
